/**
 * @name File-system access from environment configuration
 * @description Finds file operations whose paths can be influenced by OpenTelemetry SDK environment-variable configuration.
 * @kind path-problem
 * @problem.severity warning
 * @id py/otel-env-fs-access
 * @tags security
 *       external/cwe/cwe-073
 */
import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module EnvConfigToFsConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Any read from os.environ or os.getenv
    exists(RemoteFlowSource rfs | source = rfs)
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa | sink = fa.getAPathArgument())
  }
}

module EnvFsFlow = TaintTracking::Global<EnvConfigToFsConfig>;
import EnvFsFlow::PathGraph

from EnvFsFlow::PathNode source, EnvFsFlow::PathNode sink
where EnvFsFlow::flowPath(source, sink)
select sink.getNode(), source, sink,
  "Environment-derived value reaches file-system path $@.",
  source.getNode(), "env-derived path"
